class Solution:
    def minAbsDifference(self, nums: list[int], goal: int) -> int:
        best = abs(goal)
        def dfs(i: int, total: int) -> None:
            nonlocal best
            if i == len(nums):
                best = min(best, abs(goal - total))
                return
            dfs(i + 1, total)
            dfs(i + 1, total + nums[i])
        dfs(0, 0)
        return best

